<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\ValueObject\Accessor\UserEmailAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserEmailAccessor trait.
 *
 * Covers null default, string/VO assignment via withEmail,
 * getEmail/email accessors, and isEmailChanged with/without original.
 */
class UserEmailAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withEmail creates a new instance with the Email set
     * from a string value, and getEmail returns the primitive string.
     */
    public function testWithEmailFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserEmailAccessorUnitTest();

        // Act
        $result = $holder->withEmail('one@fakemail.net');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one@fakemail.net', $result->getEmail());
    }
    /**
     * Asserts that withemail has access to the value object
     * from a string value, and getEmail returns the primitive string.
     */
    public function testWithEmailFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserEmailAccessorUnitTest();

        // Act
        $result = $holder->withEmail('one@fakemail.net');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one@fakemail.net', $result->email()->value());
    }
    public function testChangedEmail(): void
    {
        // Arrange
        $holder = new ImplWithUserEmailAccessorUnitTest();
        $original = $holder->withEmail('one@fakemail.net');
        $same = $holder->withEmail('one@fakemail.net');
        $modified = $holder->withEmail('other@fakemail.net');

        // Act
        $unchanged = $holder->isEmailChanged();
        $withSame = $original->isEmailChanged($same);
        $withDiferent = $original->isEmailChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserEmailAccessorUnitTest
{
    use UserEmailAccessor;
}
